const config = {
  "previewFeatures": [],
  "clientVersion": "7.5.0",
  "engineVersion": "280c870be64f457428992c43c1f6d557fab6e29e",
  "activeProvider": "sqlite",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ==========================================\n// Раздел X ТЗ — Модель данных ВЕТАИ\n// ==========================================\n\n/// Ферма или производственная площадка верхнего уровня\nmodel Farm {\n  id        String   @id @default(cuid())\n  name      String\n  location  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  groups          GroupUnit[]\n  cows            Cow[]\n  afimilkDayMilk  AfimilkDayMilk[]\n  events          Event[]\n  tasks           Task[]\n  economic        EconomicFact[]\n  reportTemplates ReportTemplate[]\n  reportInstances ReportInstance[]\n\n  barns          Barn[]\n  sections       Section[]\n  operations     OperationRequest[]\n  dashboards     DashboardSnapshot[]\n  outboxMessages OutboxMessage[]\n}\n\n/// Логическая производственная группа животных\nmodel GroupUnit {\n  id          String   @id @default(cuid())\n  farmId      String\n  name        String\n  type        String // feeding_group | production_group | maternity\n  headCount   Int      @default(0)\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  farm           Farm                  @relation(fields: [farmId], references: [id])\n  cows           Cow[]\n  memberships    GroupMembership[]\n  sectionHistory GroupSectionHistory[]\n  events         Event[]\n  feedRecords    FeedRecord[]\n}\n\n/// Основной объект учета — корова\nmodel Cow {\n  id               String    @id @default(cuid())\n  farmId           String\n  groupId          String?\n  barnId           String?\n  currentSectionId String?\n  afiId            String\n  number           String // Бирка / номер\n  name             String?\n  birthDate        DateTime?\n  status           String    @default(\"active\") // active | dry | culled | dead\n  lactation        Int       @default(0)\n  dim              Int       @default(0) // Days in Milk\n  lastCalving      DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  farm           Farm                @relation(fields: [farmId], references: [id])\n  group          GroupUnit?          @relation(fields: [groupId], references: [id])\n  barn           Barn?               @relation(fields: [barnId], references: [id])\n  currentSection Section?            @relation(fields: [currentSectionId], references: [id])\n  externalIds    ExternalIdentity[]\n  memberships    GroupMembership[]\n  sectionHistory CowSectionHistory[]\n  milkRecords    MilkRecord[]\n  dayMilkRecords AfimilkDayMilk[]\n  events         Event[]\n  observations   Observation[]\n  geneticIndex   GeneticIndexValue[]\n  operations     OperationRequest[]\n  tasks          Task[]\n  cowEvents      CowEvent[]\n\n  @@index([farmId, afiId])\n}\n\n/// Физическая секция/загон размещения животных\nmodel Section {\n  id           String   @id @default(cuid())\n  farmId       String\n  barnId       String?\n  name         String\n  type         String?\n  externalCode String?\n  dtmCode      String?\n  afiCode      String?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  farm              Farm                  @relation(fields: [farmId], references: [id])\n  barn              Barn?                 @relation(fields: [barnId], references: [id])\n  currentCows       Cow[]\n  events            Event[]\n  cowSectionHistory CowSectionHistory[]\n  groupHistory      GroupSectionHistory[]\n\n  @@unique([farmId, name])\n  @@index([farmId, isActive])\n}\n\n/// История размещения коровы по секциям\nmodel CowSectionHistory {\n  id        String    @id @default(cuid())\n  cowId     String\n  sectionId String\n  startDate DateTime\n  endDate   DateTime?\n  source    String    @default(\"import\")\n  createdAt DateTime  @default(now())\n\n  cow     Cow     @relation(fields: [cowId], references: [id])\n  section Section @relation(fields: [sectionId], references: [id])\n\n  @@index([cowId, startDate])\n  @@index([sectionId, startDate])\n}\n\n/// История размещения группы в секции\nmodel GroupSectionHistory {\n  id        String    @id @default(cuid())\n  groupId   String\n  sectionId String\n  startDate DateTime\n  endDate   DateTime?\n  source    String    @default(\"import\")\n  createdAt DateTime  @default(now())\n\n  group   GroupUnit @relation(fields: [groupId], references: [id])\n  section Section   @relation(fields: [sectionId], references: [id])\n\n  @@index([groupId, startDate])\n  @@index([sectionId, startDate])\n}\n\n/// Сопоставление внутренних ID с внешними системами\nmodel ExternalIdentity {\n  id         String @id @default(cuid())\n  cowId      String\n  source     String // afimilk | aic | dtm | waikato | 1c\n  externalId String\n\n  cow Cow @relation(fields: [cowId], references: [id])\n\n  @@unique([cowId, source])\n  @@index([externalId, source])\n}\n\n/// История принадлежности коровы к группе\nmodel GroupMembership {\n  id        String    @id @default(cuid())\n  cowId     String\n  groupId   String\n  startDate DateTime\n  endDate   DateTime?\n  source    String    @default(\"import\")\n\n  cow   Cow       @relation(fields: [cowId], references: [id])\n  group GroupUnit @relation(fields: [groupId], references: [id])\n\n  @@index([cowId, startDate])\n}\n\n/// Источник данных (AfiFarm, DTM, Waikato, VideoAI, ручной ввод)\nmodel DataSource {\n  id          String    @id @default(cuid())\n  name        String    @unique\n  type        String // api | file | manual | video\n  description String?\n  lastSync    DateTime?\n  status      String    @default(\"active\") // active | error | disabled\n  config      String? // JSON config\n\n  batches        IntegrationBatch[]\n  outboxMessages OutboxMessage[]\n}\n\n/// Пакет загрузки данных из источника\nmodel IntegrationBatch {\n  id              String    @id @default(cuid())\n  sourceId        String\n  source          String?\n  filename        String?\n  fileHash        String?\n  status          String    @default(\"pending\") // pending | processing | completed | error\n  startedAt       DateTime?\n  finishedAt      DateTime?\n  recordsRead     Int       @default(0)\n  recordsInserted Int       @default(0)\n  recordsUpdated  Int       @default(0)\n  recordsSkipped  Int       @default(0)\n  errorMessage    String?\n  recordCount     Int       @default(0)\n  errors          String? // JSON array of errors\n  processedAt     DateTime?\n  createdAt       DateTime  @default(now())\n\n  dataSource  DataSource       @relation(fields: [sourceId], references: [id])\n  milkRecords MilkRecord[]\n  feedRecords FeedRecord[]\n  mixBatches  MixBatch[]\n  dayMilk     AfimilkDayMilk[]\n\n  @@index([sourceId, createdAt])\n}\n\n/// Справочник метрик системы\nmodel MetricDefinition {\n  id      String  @id @default(cuid())\n  code    String  @unique // yield_total, scc_avg, feed_cost_per_head\n  name    String\n  unit    String // кг, тыс/мл, ₽, %, балл\n  formula String?\n  source  String? // afimilk | aic | dtm | calculated\n\n  values MetricValue[]\n}\n\n/// Значения метрик, привязанные к объекту и моменту времени\nmodel MetricValue {\n  id         String   @id @default(cuid())\n  metricId   String\n  objectType String // farm | group | cow\n  objectId   String // ID фермы, группы или коровы\n  value      Float\n  timestamp  DateTime\n  source     String   @default(\"import\") // import | calculated | manual | estimated\n  quality    String   @default(\"ok\") // ok | estimated | conflict | missing\n\n  metric MetricDefinition @relation(fields: [metricId], references: [id])\n\n  @@index([metricId, objectType, objectId, timestamp])\n  @@index([timestamp])\n}\n\n/// Запись доения\nmodel MilkRecord {\n  id           String   @id @default(cuid())\n  cowId        String?\n  cowNumber    String\n  date         DateTime\n  session      Int      @default(1) // 1=утро, 2=день, 3=вечер\n  yield        Float // кг\n  conductivity Float?\n  scc          Float? // соматические клетки\n  duration     Float? // минуты\n  completeness Float? // %\n  stall        String?\n  source       String   @default(\"aic\") // aic | afimilk | manual\n  batchId      String?\n  createdAt    DateTime @default(now())\n\n  cow   Cow?              @relation(fields: [cowId], references: [id])\n  batch IntegrationBatch? @relation(fields: [batchId], references: [id])\n\n  @@unique([cowNumber, date, session, source])\n  @@index([cowNumber, date])\n  @@index([date, session])\n}\n\n/// Дневные агрегаты из AFI DAY_MILK.DAT\nmodel AfimilkDayMilk {\n  id             String   @id @default(cuid())\n  farmId         String\n  cowId          String?\n  cowNumber      String\n  date           DateTime\n  avg10Session1  Float\n  actualSession1 Float\n  avg10Session2  Float\n  actualSession2 Float\n  avg10Session3  Float\n  actualSession3 Float\n  avg10Total     Float\n  actualTotal    Float\n  batchId        String?\n  sourceFile     String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  farm  Farm              @relation(fields: [farmId], references: [id])\n  cow   Cow?              @relation(fields: [cowId], references: [id])\n  batch IntegrationBatch? @relation(fields: [batchId], references: [id])\n\n  @@unique([farmId, cowNumber, date])\n  @@index([farmId, date])\n  @@index([cowId, date])\n  @@index([cowNumber, date])\n}\n\n/// Запись кормления\nmodel FeedRecord {\n  id              String   @id @default(cuid())\n  groupId         String?\n  groupName       String\n  date            DateTime\n  recipe          String?\n  planned         Float? // кг запланировано\n  actual          Float? // кг фактически\n  remainder       Float? // кг остаток\n  dryMatter       Float? // кг сухого вещества\n  headCount       Int? // голов в загоне\n  milkYield       Float? // надой молока группы кг\n  iofc            Float? // IOFC ₽\n  feedCostPerHead Float? // себестоимость корма на 1 голову ₽\n  groupType       String? // Дойные | Молодняк | Сухостой\n  corrPercent     Float? // корреляция %\n  targetWeight    Float? // целевой вес на индикаторе кг\n  feedingCount    Int? // ежедневное кормление (раз)\n  source          String   @default(\"dtm\")\n  batchId         String?\n  createdAt       DateTime @default(now())\n\n  group GroupUnit?        @relation(fields: [groupId], references: [id])\n  batch IntegrationBatch? @relation(fields: [batchId], references: [id])\n\n  @@index([date, groupName])\n}\n\n// ==========================================\n// Фаза 3 — Расширенная модель кормления\n// ==========================================\n\n/// Рецепт кормления (рацион)\nmodel FeedRecipe {\n  id          String   @id @default(cuid())\n  code        String   @unique\n  name        String\n  description String?\n  targetDM    Float? // Целевое СВ, кг\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  ingredients RecipeIngredient[]\n  mixBatches  MixBatch[]\n}\n\n/// Ингредиент корма\nmodel FeedIngredient {\n  id        String @id @default(cuid())\n  code      String @unique\n  name      String\n  unit      String @default(\"кг\")\n  dmPercent Float? // % сухого вещества\n  costPerKg Float? // стоимость ₽/кг\n\n  recipes      RecipeIngredient[]\n  consumptions IngredientConsumption[]\n}\n\n/// Связь ингредиент ↔ рецепт (план)\nmodel RecipeIngredient {\n  id           String @id @default(cuid())\n  recipeId     String\n  ingredientId String\n  targetWeight Float // кг целевой\n  order        Int    @default(0)\n\n  recipe     FeedRecipe     @relation(fields: [recipeId], references: [id])\n  ingredient FeedIngredient @relation(fields: [ingredientId], references: [id])\n\n  @@unique([recipeId, ingredientId])\n}\n\n/// Запись замеса (из DTM «История замеса»)\nmodel MixBatch {\n  id            String   @id @default(cuid())\n  dtmBatchId    Int? // ID замеса из DTM\n  recipeId      String?\n  recipeName    String\n  groupCode     String? // Код загона\n  headCount     Int? // количество голов\n  date          DateTime\n  startTime     String? // HH:MM:SS\n  endTime       String? // HH:MM:SS\n  loadDuration  String? // 00:27:06\n  mixDuration   String? // 00:14:13\n  mixer         String? // Трактор 1/2\n  pauseDuration String?\n  totalDuration String?\n  source        String   @default(\"dtm\")\n  batchId       String? // IntegrationBatch\n\n  recipe       FeedRecipe?             @relation(fields: [recipeId], references: [id])\n  batch        IntegrationBatch?       @relation(fields: [batchId], references: [id])\n  consumptions IngredientConsumption[]\n\n  @@index([date, groupCode])\n}\n\n/// Потребление ингредиента в замесе (DTM «Потребление ингредиентов»)\nmodel IngredientConsumption {\n  id               String   @id @default(cuid())\n  mixBatchId       String?\n  ingredientId     String?\n  ingredientCode   String? // ID ингредиента из DTM\n  ingredientName   String\n  targetWeight     Float? // план кг\n  indicatorWeight  Float? // целевой вес на индикаторе кг\n  actualWeight     Float? // факт загружено кг\n  loadedDM         Float? // загружено СВ кг\n  errorPercent     Float? // ошибка %\n  errorAbsPercent  Float? // погрешность в % от нагрузки (АБС)\n  totalConsumption Float? // общая потребность кг\n  date             DateTime\n\n  mixBatch   MixBatch?       @relation(fields: [mixBatchId], references: [id])\n  ingredient FeedIngredient? @relation(fields: [ingredientId], references: [id])\n\n  @@index([date, ingredientName])\n}\n\n/// Тип события\nmodel EventType {\n  id       String @id @default(cuid())\n  code     String @unique\n  name     String\n  category String // health | reproduction | feeding | milking | system\n  severity String @default(\"info\") // info | warning | critical\n\n  events Event[]\n}\n\n/// Фактическое событие\nmodel Event {\n  id          String   @id @default(cuid())\n  typeId      String?\n  cowId       String?\n  groupId     String?\n  sectionId   String?\n  farmId      String?\n  severity    String   @default(\"info\")\n  title       String\n  description String?\n  timestamp   DateTime\n  source      String   @default(\"system\")\n  metadata    String? // JSON\n\n  // Provenance & Trust Layer\n  receivedAt         DateTime?\n  sourceRecordId     String?\n  dedupeKey          String?\n  confirmationStatus String    @default(\"UNCONFIRMED\") // UNCONFIRMED, CONFIRMED_HUMAN, CONFLICT, SOURCE_OK\n  confirmedAt        DateTime?\n  confirmedById      String?\n  confidenceScore    Float?\n\n  type    EventType? @relation(fields: [typeId], references: [id])\n  cow     Cow?       @relation(fields: [cowId], references: [id])\n  group   GroupUnit? @relation(fields: [groupId], references: [id])\n  section Section?   @relation(fields: [sectionId], references: [id])\n  farm    Farm?      @relation(fields: [farmId], references: [id])\n\n  outboxMessages OutboxMessage[]\n  tasks          Task[]\n\n  @@index([timestamp])\n  @@index([cowId, timestamp])\n  @@index([groupId, timestamp])\n  @@index([sectionId, timestamp])\n  @@index([severity, timestamp])\n}\n\n/// Наблюдения от видеоаналитики/сенсоров\nmodel Observation {\n  id           String   @id @default(cuid())\n  cowId        String?\n  type         String // bcs | lameness | activity\n  value        Float\n  confidence   Float?\n  modelVersion String?\n  cameraId     String?\n  videoRef     String? // ссылка на видеофрагмент\n  timestamp    DateTime\n  verified     Boolean  @default(false)\n\n  cow Cow? @relation(fields: [cowId], references: [id])\n\n  @@index([cowId, type, timestamp])\n}\n\n/// Экономические показатели\nmodel EconomicFact {\n  id     String   @id @default(cuid())\n  farmId String\n  type   String // feed_cost | milk_revenue | gross_margin\n  value  Float\n  period DateTime\n  source String   @default(\"manual\")\n\n  farm Farm @relation(fields: [farmId], references: [id])\n\n  @@index([farmId, type, period])\n}\n\n/// Генетические показатели коровы\nmodel GeneticIndexValue {\n  id    String   @id @default(cuid())\n  cowId String\n  index String // productivity | fertility | health\n  value Float\n  date  DateTime\n\n  cow Cow @relation(fields: [cowId], references: [id])\n\n  @@index([cowId, index])\n}\n\n// ==========================================\n// Фаза 4 — Модуль Отчетности V2 (Reporting)\n// ==========================================\n\n/// Шаблон отчета\nmodel ReportTemplate {\n  id            String   @id @default(cuid())\n  code          String\n  name          String\n  description   String?\n  reportType    String // REGULATORY, BREEDING, VETERINARY, PRODUCTION, MANAGEMENT\n  authority     String // MINSKHOZ, ROSSTAT, VET_SERVICE, INTERNAL, BREEDING_REGISTRY, OTHER\n  version       String\n  defaultFormat String // XLSX, PDF, CSV, JSON\n  isSystem      Boolean  @default(true)\n  isActive      Boolean  @default(true)\n  configJson    String? // Stored as String (JSON) since SQLite doesn't natively support Json type well without Prisma extensions, or we use String\n  schemaJson    String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  farmId String?\n  farm   Farm?   @relation(fields: [farmId], references: [id])\n\n  sections  ReportSection[]\n  instances ReportInstance[]\n\n  @@unique([code, version])\n  @@index([reportType, authority, isActive])\n}\n\n/// Секции шаблона\nmodel ReportSection {\n  id         String   @id @default(cuid())\n  templateId String\n  title      String\n  code       String\n  sortOrder  Int\n  configJson String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  template ReportTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  lines    ReportLine[]\n\n  @@index([templateId, sortOrder])\n}\n\n/// Строки/метрики шаблона\nmodel ReportLine {\n  id           String   @id @default(cuid())\n  sectionId    String\n  code         String\n  label        String\n  valueType    String\n  formula      String?\n  sourceEntity String?\n  sourceField  String?\n  sortOrder    Int\n  isRequired   Boolean  @default(false)\n  configJson   String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  section ReportSection @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n\n  @@index([sectionId, sortOrder])\n}\n\n/// Экземпляры отчетов\nmodel ReportInstance {\n  id            String    @id @default(cuid())\n  templateId    String\n  farmId        String\n  title         String\n  periodStart   DateTime\n  periodEnd     DateTime\n  reportDate    DateTime\n  status        String    @default(\"DRAFT\") // DRAFT, GENERATED, VALIDATION_ERROR, READY_FOR_REVIEW, APPROVED, EXPORTED, SUBMITTED, ACCEPTED, REJECTED, REVISED\n  format        String // XLSX, PDF, CSV, JSON\n  versionNumber Int       @default(1)\n  payloadJson   String?\n  summaryJson   String?\n  fileUrl       String?\n  generatedAt   DateTime?\n  approvedAt    DateTime?\n  submittedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  createdById  String?\n  approvedById String?\n\n  template         ReportTemplate          @relation(fields: [templateId], references: [id])\n  farm             Farm                    @relation(fields: [farmId], references: [id])\n  validationIssues ReportValidationIssue[]\n  exports          ReportExportJob[]\n  submissions      ReportSubmission[]\n  auditLogs        ReportAuditLog[]\n\n  @@index([farmId, status])\n  @@index([templateId, periodStart, periodEnd])\n  @@index([reportDate])\n}\n\n/// Ошибки валидации\nmodel ReportValidationIssue {\n  id               String   @id @default(cuid())\n  reportInstanceId String\n  severity         String // INFO, WARNING, ERROR, CRITICAL\n  code             String\n  message          String\n  entityType       String?\n  entityId         String?\n  fieldName        String?\n  detailsJson      String?\n  createdAt        DateTime @default(now())\n\n  reportInstance ReportInstance @relation(fields: [reportInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([reportInstanceId, severity])\n}\n\n/// Экспорт\nmodel ReportExportJob {\n  id               String    @id @default(cuid())\n  reportInstanceId String\n  format           String // XLSX, PDF, CSV, JSON\n  status           String // PENDING, PROCESSING, COMPLETED, FAILED\n  fileUrl          String?\n  errorMessage     String?\n  createdAt        DateTime  @default(now())\n  completedAt      DateTime?\n\n  reportInstance ReportInstance @relation(fields: [reportInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([reportInstanceId, format])\n}\n\n/// Отправка/сабмит\nmodel ReportSubmission {\n  id               String    @id @default(cuid())\n  reportInstanceId String\n  channel          String // MANUAL, FILE_EXPORT, API\n  status           String    @default(\"NOT_SENT\") // NOT_SENT, SENT, ACCEPTED, REJECTED, NEEDS_CORRECTION\n  externalSystem   String?\n  externalId       String?\n  sentAt           DateTime?\n  responseJson     String?\n  errorMessage     String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  reportInstance ReportInstance @relation(fields: [reportInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([reportInstanceId, status])\n}\n\n/// Аудит\nmodel ReportAuditLog {\n  id               String   @id @default(cuid())\n  reportInstanceId String\n  action           String\n  actorId          String?\n  actorName        String?\n  beforeJson       String?\n  afterJson        String?\n  comment          String?\n  createdAt        DateTime @default(now())\n\n  reportInstance ReportInstance @relation(fields: [reportInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([reportInstanceId, createdAt])\n}\n\n// ==========================================\n// Фаза 5 — Модули \"Контроль AfiMilk\" и \"Инфографика\"\n// ==========================================\n\nmodel Barn {\n  id         String             @id @default(cuid())\n  farmId     String\n  name       String\n  farm       Farm               @relation(fields: [farmId], references: [id])\n  cows       Cow[]\n  sections   Section[]\n  operations OperationRequest[]\n  createdAt  DateTime           @default(now())\n  updatedAt  DateTime           @updatedAt\n}\n\nmodel OperationRequest {\n  id                        String                   @id @default(cuid())\n  farmId                    String\n  barnId                    String?\n  cowId                     String\n  afiCowExternalId          String?\n  operationType             String // INSEMINATION, TREATMENT, GROUP_TRANSFER, etc.\n  title                     String\n  description               String?\n  eventDate                 DateTime\n  dueDate                   DateTime?\n  priority                  String                   @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, CRITICAL\n  source                    String                   @default(\"MANUAL\") // MANUAL, AUTO_RULE, ALERT, IMPORTED, MOBILE_APP\n  status                    String                   @default(\"CREATED\") // DRAFT, CREATED, PENDING_AFIMILK_ENTRY, IN_PROGRESS, ENTERED_IN_AFIMILK, etc.\n  severity                  String?\n  isCriticalForReporting    Boolean                  @default(false)\n  isCriticalForReproduction Boolean                  @default(false)\n  isCriticalForVeterinary   Boolean                  @default(false)\n  requiresVerification      Boolean                  @default(true)\n  createdById               String\n  assignedToId              String?\n  confirmedAt               DateTime?\n  confirmedById             String?\n  rejectedAt                DateTime?\n  rejectedById              String?\n  rejectionReason           String?\n  externalReference         String?\n  comment                   String?\n  farm                      Farm                     @relation(fields: [farmId], references: [id])\n  barn                      Barn?                    @relation(fields: [barnId], references: [id])\n  cow                       Cow                      @relation(fields: [cowId], references: [id])\n  confirmations             OperationConfirmation[]\n  statusHistory             OperationStatusHistory[]\n  comments                  OperationComment[]\n  attachments               OperationAttachment[]\n  outboxMessages            OutboxMessage[]\n  createdAt                 DateTime                 @default(now())\n  updatedAt                 DateTime                 @updatedAt\n  deletedAt                 DateTime?\n\n  @@index([farmId, status])\n  @@index([assignedToId, status])\n  @@index([cowId, status])\n  @@index([eventDate])\n  @@index([dueDate])\n}\n\nmodel OperationConfirmation {\n  id                 String           @id @default(cuid())\n  operationRequestId String\n  confirmedById      String\n  confirmedAt        DateTime\n  confirmationMethod String\n  afiEntryDate       DateTime?\n  afiEntryNumber     String?\n  note               String?\n  attachmentUrl      String?\n  operationRequest   OperationRequest @relation(fields: [operationRequestId], references: [id])\n  createdAt          DateTime         @default(now())\n}\n\nmodel OperationStatusHistory {\n  id                 String           @id @default(cuid())\n  operationRequestId String\n  oldStatus          String?\n  newStatus          String\n  changedById        String\n  changeReason       String?\n  operationRequest   OperationRequest @relation(fields: [operationRequestId], references: [id])\n  createdAt          DateTime         @default(now())\n}\n\nmodel OperationComment {\n  id                 String           @id @default(cuid())\n  operationRequestId String\n  authorId           String\n  text               String\n  operationRequest   OperationRequest @relation(fields: [operationRequestId], references: [id])\n  createdAt          DateTime         @default(now())\n}\n\nmodel OperationAttachment {\n  id                 String           @id @default(cuid())\n  operationRequestId String\n  fileName           String\n  fileUrl            String\n  fileType           String?\n  uploadedById       String\n  operationRequest   OperationRequest @relation(fields: [operationRequestId], references: [id])\n  createdAt          DateTime         @default(now())\n}\n\nmodel CowEvent {\n  id        String   @id @default(cuid())\n  farmId    String\n  cowId     String\n  eventType String\n  eventDate DateTime\n  source    String?\n  metadata  String? // Stored as String since SQLite lacks native JSON\n  cow       Cow      @relation(fields: [cowId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@index([farmId, eventType, eventDate])\n  @@index([cowId, eventDate])\n}\n\n// ==========================================\n// Фаза 6 — Модуль Уведомлений (Inbox)\n// ==========================================\n\n/// Системные и пользовательские уведомления\nmodel Notification {\n  id       String  @id @default(cuid())\n  userId   String  @default(\"system\") // Пока один пользователь, но архитектурно выделен\n  title    String\n  message  String?\n  type     String // action_required, report_alert, system_alert, info\n  priority String  @default(\"medium\") // critical, high, medium, low\n\n  // Связь с источником (polymorphic-like)\n  sourceType String? // cow, group, section, report, integration, system\n  sourceId   String?\n  link       String? // URL/route для быстрого перехода\n\n  isRead       Boolean @default(false)\n  isActionable Boolean @default(false)\n  status       String  @default(\"unread\") // unread, read, in_progress, done, dismissed\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  readAt    DateTime?\n\n  @@index([userId, isRead])\n  @@index([createdAt])\n  @@index([sourceType, sourceId])\n}\n\nmodel DashboardSnapshot {\n  id                  String   @id @default(cuid())\n  farmId              String\n  snapshotDate        DateTime\n  totalCows           Int\n  milkingCows         Int\n  dryCows             Int\n  freshCows           Int\n  avgMilkPerCow       Float?\n  totalMilkPerDay     Float?\n  alertCount          Int      @default(0)\n  criticalAlertCount  Int      @default(0)\n  pendingOperations   Int      @default(0)\n  overdueOperations   Int      @default(0)\n  completedOperations Int      @default(0)\n  treatmentCount7d    Int      @default(0)\n  inseminationCount7d Int      @default(0)\n  createdAt           DateTime @default(now())\n\n  farm Farm @relation(fields: [farmId], references: [id])\n\n  @@index([farmId, snapshotDate])\n}\n\n/// Сообщение для обратной интеграции (Writeback)\nmodel OutboxMessage {\n  id                 String    @id @default(cuid())\n  farmId             String\n  dataSourceId       String\n  operationRequestId String?\n  eventId            String?\n  payloadJson        String\n  status             String    @default(\"PENDING\") // PENDING, SENT, FAILED, ACKED\n  attempts           Int       @default(0)\n  nextRetryAt        DateTime?\n  lastAttemptAt      DateTime?\n  externalAckId      String?\n  errorMessage       String?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  farm             Farm              @relation(fields: [farmId], references: [id])\n  dataSource       DataSource        @relation(fields: [dataSourceId], references: [id])\n  operationRequest OperationRequest? @relation(fields: [operationRequestId], references: [id])\n  event            Event?            @relation(fields: [eventId], references: [id])\n\n  @@index([farmId, status])\n  @@index([dataSourceId, status])\n  @@index([nextRetryAt])\n  @@index([status])\n}\n\n/// Задача для персонала (Task Engine)\nmodel Task {\n  id          String    @id @default(cuid())\n  farmId      String\n  title       String\n  description String?\n  status      String    @default(\"TODO\") // TODO, IN_PROGRESS, DONE, CANCELLED\n  priority    String    @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, CRITICAL\n  dueDate     DateTime?\n  assigneeId  String? // vet-01, feed-02\n  cowId       String?\n  eventId     String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  farm  Farm   @relation(fields: [farmId], references: [id])\n  cow   Cow?   @relation(fields: [cowId], references: [id])\n  event Event? @relation(fields: [eventId], references: [id])\n\n  @@index([farmId, status])\n  @@index([assigneeId, status])\n  @@index([cowId])\n}\n"
}

